mapper.select:
WITH RECURSIVE closing_side_chats(thread_id) AS ( SELECT thread_id FROM ja_conversation_thread WHERE temporary_lifecycle_state='CLOSING' UNION SELECT l.child_thread_id FROM ja_conversation_lineage l JOIN closing_side_chats c ON c.thread_id=l.parent_thread_id ), discovered AS ( SELECT t.thread_id AS threadId,t.title,'MAIN' AS kind,t.workspace_id AS workspaceId, COALESCE((SELECT state FROM ja_conversation_turn x WHERE x.thread_id=t.thread_id AND x.is_current_path=1 ORDER BY x.turn_sequence DESC LIMIT 1),'IDLE') AS status,t.updated_at_ms AS updatedAt, (SELECT turn_id FROM ja_conversation_turn x WHERE x.thread_id=t.thread_id AND x.is_current_path=1 ORDER BY x.turn_sequence DESC LIMIT 1) AS latestTurnId FROM ja_conversation_thread t WHERE t.deleted_at_ms IS NULL AND t.archived_at_ms IS NULL AND NOT EXISTS (SELECT 1 FROM ja_conversation_lineage l WHERE l.child_thread_id=t.thread_id) UNION ALL SELECT t.thread_id AS threadId,t.title, CASE l.task_kind WHEN 'SIDE_TASK' THEN 'SIDE_CHAT' ELSE 'SUBAGENT' END AS kind, t.workspace_id AS workspaceId,COALESCE(p.state,'IDLE') AS status, COALESCE(p.updated_at_ms,t.updated_at_ms) AS updatedAt, (SELECT turn_id FROM ja_conversation_turn x WHERE x.thread_id=t.thread_id AND x.is_current_path=1 ORDER BY x.turn_sequence DESC LIMIT 1) AS latestTurnId FROM ja_conversation_thread t JOIN ja_conversation_lineage l ON l.child_thread_id=t.thread_id LEFT JOIN ja_task_projection p ON p.task_thread_id=l.child_thread_id WHERE t.deleted_at_ms IS NULL AND t.archived_at_ms IS NULL AND NOT EXISTS ( SELECT 1 FROM closing_side_chats c WHERE c.thread_id=l.child_thread_id ) ) SELECT threadId,title,kind,workspaceId,status,updatedAt,latestTurnId FROM discovered
workspaceId=#{workspaceId}
AND instr(lower(title),#{normalizedQuery})>0
AND (updatedAt<#{cursorTime,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT} OR (updatedAt=#{cursorTime,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT} AND threadId<#{cursorId}))
ORDER BY updatedAt DESC,threadId DESC LIMIT #{limit}
